def apply_margin_mode(self, margin_kind, symbol=None, params={}):
    margin_kind = margin_kind.upper()
    if margin_kind != 'ISOLATED' and margin_kind != 'CROSSED':
        raise BadRequest(self.id + ' marginType must be either isolated or crossed')

    self.load_markets()
    market = self.market(symbol)
    endpoint = None

    if market['linear']:
        endpoint = 'fapiPrivatePostMarginType'
    elif market['inverse']:
        endpoint = 'dapiPrivatePostMarginType'
    else:
        raise NotSupported(self.id + ' setMarginMode() supports linear and inverse contracts only')

    payload = {
        'symbol': market['id'],
        'marginType': margin_kind,
    }

    return getattr(self, endpoint)(self.extend(payload, params))

